<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { calcularProcesoPlanilla, listarTrabajadoresCalculo } from '../services/procesosPlanilla'
import type { ProcesoPlanilla, TrabajadorCalculoPlanilla } from '../interfaces/procesoPlanilla.interface'
const route=useRoute(),router=useRouter(),id=computed(()=>Number(route.query.id||0)),proceso=ref<ProcesoPlanilla|null>(null),modo=ref<'calcular'|'recalcular'>('calcular'),rows=ref<TrabajadorCalculoPlanilla[]>([]),selected=ref<number[]>([]),q=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),working=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.',money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
async function load(next=1){if(!id.value)return void(error.value='Indique el proceso mediante el parámetro ?id=.');loading.value=true;selected.value=[];error.value='';try{const r=await listarTrabajadoresCalculo(id.value,q.value,next);proceso.value=r.proceso;modo.value=r.modo;rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function selectPage(){selected.value=rows.value.map(r=>r.id)}
async function process(all:boolean){if(!proceso.value)return;if(!all&&!selected.value.length)return void(error.value='Seleccione al menos un trabajador para el cálculo personalizado.');const label=modo.value==='recalcular'?'recalcular':'calcular';if(!confirm(`¿Desea ${label} ${all?'todos los trabajadores':'los trabajadores seleccionados'}?`))return;working.value=true;error.value='';try{await calcularProcesoPlanilla(proceso.value.id,{modo:all?'TODO':'SELECCION',trabajador_ids:all?[]:selected.value});await router.push(`/modulos/administracion/recursos/detalle-proceso-planilla?id=${proceso.value.id}`)}catch(v){error.value=message(v)}finally{working.value=false}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos/procesos-planilla">Procesos</RouterLink> / Seleccionar trabajadores</nav><header v-if="proceso" class="hero"><div class="mark">{{modo==='recalcular'?'RC':'CP'}}</div><div><small>MIA · RR. HH. · PLANILLAS</small><h1>{{modo==='recalcular'?'Recalcular':'Cálculo'}} personalizado - Proceso #{{proceso.id}}</h1><p>Periodo {{proceso.mes}}/{{proceso.anio}} · {{proceso.regimen?.descripcion??'N/D'}}</p></div><strong>{{total}} disponibles</strong></header><p v-if="error" class="flash">{{error}}</p><aside>Solo se muestran trabajadores con al menos una configuración vigente y aplicable en conceptos por trabajador.</aside><form class="search" @submit.prevent="load(1)"><input v-model.trim="q" placeholder="Código, apellidos, nombres o DNI"><button>Buscar</button><button type="button" class="soft" @click="q='';load(1)">Limpiar</button></form><section class="table-card"><div class="toolbar"><button @click="selectPage">Seleccionar página</button><button class="soft" @click="selected=[]">Limpiar página</button><span>{{selected.length}} seleccionados</span></div><div v-if="loading" class="empty">Consultando trabajadores…</div><div v-else-if="!rows.length" class="empty">No se encontraron trabajadores para este proceso.</div><div v-else class="scroll"><table><thead><tr><th>Sel.</th><th>ID</th><th>Código</th><th>Trabajador</th><th>DNI</th><th>Régimen</th><th class="num">Sueldo base</th></tr></thead><tbody><tr v-for="t in rows" :key="t.id"><td><input v-model="selected" type="checkbox" :value="t.id"></td><td>#{{t.id}}</td><td><b>{{t.codigo_trabajador}}</b></td><td>{{t.nombre_completo}}</td><td>{{t.dni??'—'}}</td><td>{{t.regimen??'—'}}</td><td class="num">{{money(t.sueldo_base)}}</td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="proceso" class="actions"><button :disabled="working" @click="process(false)">{{modo==='recalcular'?'Recalcular':'Procesar'}} seleccionados</button><button class="outline" :disabled="working" @click="process(true)">{{modo==='recalcular'?'Recalcular':'Procesar'}} todo</button><RouterLink :to="`/modulos/administracion/recursos/detalle-proceso-planilla?id=${proceso.id}`">Cancelar</RouterLink></div></div></template>
<style scoped>
.page{--a:#2f91a0;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.15rem}.hero p{margin:0;color:#7e8a90;font-size:.6rem}.hero>strong{font-size:.55rem}.flash{padding:9px;color:#a64046;background:#fff0f0}aside{margin-top:12px;padding:10px;color:#68777d;background:#edf1f3;font-size:.53rem}.search{padding:12px;display:grid;grid-template-columns:1fr auto auto;gap:7px;background:#fff}.search input{padding:9px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.52rem}button,.actions a{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem;text-decoration:none}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:12px;background:#fff}.toolbar{padding:10px;display:flex;align-items:center;gap:7px}.toolbar span{font-size:.52rem}.empty{padding:45px;text-align:center}.scroll{overflow:auto}table{width:100%;min-width:800px;border-collapse:collapse;font-size:.5rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{color:#fff;background:#354a55}.num{text-align:right}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:10px;font-size:.52rem}.actions{margin-top:12px;padding:14px;display:flex;gap:8px;background:#fff}.outline{color:var(--a);background:#e3f1f3}.actions a{color:#64727a;background:#edf1f3}@media(max-width:550px){.search{grid-template-columns:1fr}.actions{flex-direction:column}}
</style>
